const dsl = `workspace "Library" "A small public library system." {
    model {
        patron = person "Patron" "Borrows books at the library."
        library = softwareSystem "Library" "Manages books and loans." {
            catalog = container "Catalog Web App" "Lets patrons browse the catalogue." "Python"
            circulation = container "Circulation Service" "Records loans and returns." "Java"
        }
        patron -> catalog "Browses the catalogue through" "HTTPS"
        catalog -> circulation "Records loans via" "gRPC"
    }
    views {
        systemContext library "SystemContext" {
            include *
            autoLayout
        }
    }
}`;

const [plantuml, c4plantuml, mermaid] = await Promise.allSettled([
  tools.structurizr["export-plantuml"]({ dsl, viewKey: "SystemContext" }),
  tools.structurizr["export-c4plantuml"]({ dsl, viewKey: "SystemContext" }),
  tools.structurizr["export-mermaid"]({ dsl, viewKey: "SystemContext" }),
]);

return {
  plantuml: plantuml.status === "fulfilled" ? plantuml.value : plantuml.reason,
  c4plantuml: c4plantuml.status === "fulfilled" ? c4plantuml.value : c4plantuml.reason,
  mermaid: mermaid.status === "fulfilled" ? mermaid.value : mermaid.reason,
};

